import os, yaml
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
def md(path, fm, body=""):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf8") as f:
        f.write("---\n" + yaml.safe_dump(fm, allow_unicode=True, sort_keys=False, width=1000) + "---\n" + body.strip() + "\n")
def R(title, text, moves, src="народное"): return dict(title=title, text=text, moves=moves, source=src)

